namespace Gordic.Pok.Dialogs {

    export function GPokDetailDokladuDlg(
        parentContent: GContent,
        input: GPokDetailDokladuDlgInputParams
    ) {
        return Gordic.Gui.Dialogs.buildDialog<GPokDetailDokladuDlgInputParams>({
            dialogName: 'Gordic.Pok.WebClient.GPokDetailDokladuTab',
            id: '"GPokDetailDokladu#',
            openDialogParams: {
                parentContent: parentContent,
                opt: input
            }
        });
    }

    export interface GPokDetailDokladuDlgInputParams {
        /**
         * Ixp dokumentu.
         */
        Ixp: string
    }


}